actions.command:
$p = {path}
$d = if (Test-Path -LiteralPath $p -PathType Container) { $p } else { Split-Path -Parent $p }
& git -C $d rev-parse --abbrev-ref HEAD

$root = {dir}
$leaf = Split-Path -Leaf $root; if (-not $leaf) { $leaf = $root }
$skipBuild = @('.git','node_modules','.vs','__pycache__','bin','obj','dist','build','.next','.venv','venv','target','.gradle','.idea')

function Get-Sorted([string]$p, [bool]$nobuild) {
  $k = @(Get-ChildItem -LiteralPath $p -ErrorAction SilentlyContinue | Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) })
  if ($nobuild) { $k = @($k | Where-Object { -not ($_.PSIsContainer -and ($script:skipBuild -contains $_.Name)) }) }
  @($k | Where-Object { $_.PSIsContainer } | Sort-Object { $_.Name.ToUpperInvariant() }) + @($k | Where-Object { -not $_.PSIsContainer } | Sort-Object { $_.Name.ToUpperInvariant() })
}

$all = New-Object System.Collections.ArrayList
function Walk([string]$p, [int]$depth, [string]$rel, [bool]$nobuild, [int]$maxDepth) {
  foreach ($it in (Get-Sorted $p $nobuild)) {
    $r = if ($rel) { $rel + '\' + $it.Name } else { $it.Name }
    [void]$all.Add([pscustomobject]@{ Rel = $r; Name = $it.Name; Dir = [bool]$it.PSIsContainer; Size = $(if ($it.PSIsContainer) { [int64]0 } else { [int64]$it.Length }); Modified = $it.LastWriteTime; Depth = $depth; Full = $it.FullName })
    if ($it.PSIsContainer -and ($maxDepth -le 0 -or $depth -lt $maxDepth)) { Walk $it.FullName ($depth + 1) $r $nobuild $maxDepth }
  }
}

function Fmt([double]$b) {
  $c = [Globalization.CultureInfo]::InvariantCulture
  if ($b -lt 1024) { return ([int64]$b).ToString($c) + ' B' }
  if ($b -lt 1MB) { return [string]::Format($c, '{0:0.0} KB', $b / 1KB) }
  if ($b -lt 1GB) { return [string]::Format($c, '{0:0.0} MB', $b / 1MB) }
  return [string]::Format($c, '{0:0.0} GB', $b / 1GB)
}

function Render($items, [string]$T, [string]$L, [string]$V, [string]$S) {
  $out = New-Object System.Collections.ArrayList
  $n = $items.Count
  $isLast = New-Object 'bool[]' $n
  for ($i = 0; $i -lt $n; $i++) {
    $j = $i + 1
    while ($j -lt $n -and $items[$j].Depth -gt $items[$i].Depth) { $j++ }
    $isLast[$i] = ($j -ge $n -or $items[$j].Depth -lt $items[$i].Depth)
  }
  $anc = New-Object 'bool[]' 64
  for ($i = 0; $i -lt $n; $i++) {
    $it = $items[$i]; $d = $it.Depth
    $anc[$d - 1] = $isLast[$i]
    $pre = ''
    for ($k = 0; $k -lt $d - 1; $k++) { $pre += $(if ($anc[$k]) { $S } else { $V }) }
    $pre += $(if ($isLast[$i]) { $L } else { $T })
    [void]$out.Add([pscustomobject]@{ Text = $pre + $it.Name + $(if ($it.Dir) { '/' } else { '' }); Item = $it })
  }
  $out
}

$T = [string][char]0x251C + [char]0x2500 + [char]0x2500 + ' '
$L = [string][char]0x2514 + [char]0x2500 + [char]0x2500 + ' '
$V = [string][char]0x2502 + '   '
$S = '    '
Walk $root 1 '' $false 0
$nodes = @($all)

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add($leaf + '/')
foreach ($r in (Render $nodes $T $L $V $S)) { $lines.Add($r.Text) }
$lines -join "`n"

$root = {dir}
$leaf = Split-Path -Leaf $root; if (-not $leaf) { $leaf = $root }
$skipBuild = @('.git','node_modules','.vs','__pycache__','bin','obj','dist','build','.next','.venv','venv','target','.gradle','.idea')

