  if ($binExt -contains $ext) { return $true }
  try { $fs = [IO.File]::OpenRead($f); try { $buf = New-Object byte[] 8192; $n = $fs.Read($buf, 0, 8192); for ($i = 0; $i -lt $n; $i++) { if ($buf[$i] -eq 0) { return $true } } } finally { $fs.Dispose() } } catch { return $true }
  $false
}
function Build-Ai([string]$title, $entries) {
  $sb = New-Object System.Text.StringBuilder
  $skipBin = New-Object System.Collections.Generic.List[string]; $skipBig = New-Object System.Collections.Generic.List[string]; $skipCap = New-Object System.Collections.Generic.List[string]
  $included = 0; $total = 0
  foreach ($e in $entries) {
    $name = [IO.Path]::GetFileName($e.Full)
    if ($lockNames -contains $name) { continue }
    if (Test-Binary $e.Full) { $skipBin.Add($e.Rel); continue }
    $len = (Get-Item -LiteralPath $e.Full).Length
    if ($len -gt $maxFile) { $skipBig.Add($e.Rel); continue }
    if ($total + $len -gt $maxTotal) { $skipCap.Add($e.Rel); continue }
    $text = [IO.File]::ReadAllText($e.Full).TrimEnd("`r", "`n")
    $ext = [IO.Path]::GetExtension($name).ToLowerInvariant()
    $l = if ($lang.ContainsKey($ext)) { $lang[$ext] } else { '' }
    [void]$sb.Append("`n### " + $e.Rel + "`n`n``````" + $l + "`n" + $text + "`n``````" + "`n")
    $included++; $total += $len
  }
  $parts = @()
  if ($skipBin.Count) { $parts += ('{0} binary' -f $skipBin.Count) }
  if ($skipBig.Count) { $parts += ('{0} large' -f $skipBig.Count) }
  if ($skipCap.Count) { $parts += ('{0} over the size limit' -f $skipCap.Count) }
  if ($parts.Count) { $names = @($skipBin + $skipBig + $skipCap | Select-Object -First 5) -join ', '; [void]$sb.Append("`nSkipped: " + ($parts -join ', ') + ' (' + $names + ")`n") }
  $tokens = [int][Math]::Ceiling($sb.Length / 4.0)
  [pscustomobject]@{ Text = $sb.ToString(); Files = $included; Chars = $sb.Length; Tokens = $tokens }
}

