function Get-RepoInfo([string]$p) {
  $d = if (Test-Path -LiteralPath $p -PathType Container) { $p } else { Split-Path -Parent $p }
  $top = (& git -C $d rev-parse --show-toplevel 2>$null)
  if ($LASTEXITCODE -ne 0 -or -not $top) { return $null }
  $url = (& git -C $d remote get-url origin 2>$null)
  if ($LASTEXITCODE -ne 0 -or -not $url) { $first = @(& git -C $d remote 2>$null)[0]; if ($first) { $url = (& git -C $d remote get-url $first 2>$null) } }
  if (-not $url) { return [pscustomobject]@{ Top = ([string]$top).Replace('/', '\'); Dir = $d; Url = $null; Web = $null; Host = $null } }
  $u = [string]$url; $u = $u.Trim()
  $web = $u
  if ($u -match '^git@([^:]+):(.+)$') { $web = 'https://' + $Matches[1] + '/' + $Matches[2] }
  elseif ($u -match '^ssh://(?:[^@]+@)?([^/:]+)(?::\d+)?/(.+)$') { $web = 'https://' + $Matches[1] + '/' + $Matches[2] }
  $web = ($web -replace '\.git$', '').TrimEnd('/')
  $web = $web -replace '^https://[^@/]+@', 'https://'
  $hostName = ([Uri]$web).Host
  [pscustomobject]@{ Top = ([string]$top).Replace('/', '\'); Dir = $d; Url = $u; Web = $web; Host = $hostName }
}
function Get-Permalink($info, [string]$file, [string]$sha) {
  $rel = $file.Substring($info.Top.TrimEnd('\').Length + 1).Replace('\', '/')
  $enc = ($rel -split '/' | ForEach-Object { [Uri]::EscapeDataString($_) }) -join '/'
  if ($info.Host -like '*dev.azure.com' -or $info.Host -like '*visualstudio.com') { return $info.Web + '?path=/' + $enc + '&version=GC' + $sha }
  if ($info.Host -like '*gitlab*') { return $info.Web + '/-/blob/' + $sha + '/' + $enc }
  if ($info.Host -like '*bitbucket*') { return $info.Web + '/src/' + $sha + '/' + $enc }
  $info.Web + '/blob/' + $sha + '/' + $enc
}

