Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class PstLock {
  [StructLayout(LayoutKind.Sequential)] struct RM_UNIQUE_PROCESS { public int dwProcessId; public System.Runtime.InteropServices.ComTypes.FILETIME ProcessStartTime; }
  [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Auto)] struct RM_PROCESS_INFO {
    public RM_UNIQUE_PROCESS Process;
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 256)] public string strAppName;
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)] public string strServiceShortName;
    public int ApplicationType; public uint AppStatus; public uint TSSessionId;
    [MarshalAs(UnmanagedType.Bool)] public bool bRestartable; }
  [DllImport("rstrtmgr.dll", CharSet = CharSet.Unicode)] static extern int RmStartSession(out uint h, int flags, string key);
  [DllImport("rstrtmgr.dll")] static extern int RmEndSession(uint h);
  [DllImport("rstrtmgr.dll", CharSet = CharSet.Unicode)] static extern int RmRegisterResources(uint h, uint nFiles, string[] files, uint nApps, RM_UNIQUE_PROCESS[] apps, uint nSvc, string[] svcs);
  [DllImport("rstrtmgr.dll")] static extern int RmGetList(uint h, out uint needed, ref uint count, [In, Out] RM_PROCESS_INFO[] info, ref uint reasons);
  public static List<string[]> Who(string[] files) {
    var result = new List<string[]>();
    uint h; if (RmStartSession(out h, 0, Guid.NewGuid().ToString()) != 0) return result;
    try {
      if (RmRegisterResources(h, (uint)files.Length, files, 0, null, 0, null) != 0) return result;
      uint needed = 0, count = 0, reasons = 0;
      int r = RmGetList(h, out needed, ref count, null, ref reasons);
      if (r == 234 && needed > 0) {
        var info = new RM_PROCESS_INFO[needed]; count = needed;
        r = RmGetList(h, out needed, ref count, info, ref reasons);
        if (r == 0) for (int i = 0; i < count; i++) result.Add(new[] { info[i].strAppName, info[i].Process.dwProcessId.ToString(), info[i].ApplicationType.ToString() });
      }
    } finally { RmEndSession(h); }
    return result;
  }
}
'@
$p = {path}
$files = @($p)
if (Test-Path -LiteralPath $p -PathType Container) { $files = @(Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 5000 | ForEach-Object { $_.FullName }) }
$types = @{ '0' = 'Unknown'; '1' = 'Application'; '2' = 'Window'; '3' = 'Service'; '4' = 'Explorer'; '5' = 'Console'; '1000' = 'Critical' }
$seen = @{}
$rows = New-Object System.Collections.ArrayList
foreach ($chunk in 0..([Math]::Max(0, [Math]::Ceiling($files.Count / 200.0) - 1))) {
  $part = @($files | Select-Object -Skip ($chunk * 200) -First 200)
  if ($part.Count -eq 0) { continue }
  foreach ($w in [PstLock]::Who([string[]]$part)) {
    if ($seen.ContainsKey($w[1])) { continue }
    $seen[$w[1]] = $true
    $an = $w[0]; if (-not $an -or -not $an.Trim()) { $pr = Get-Process -Id ([int]$w[1]) -ErrorAction SilentlyContinue; $an = if ($pr) { $pr.ProcessName } else { 'Unknown' } }
    [void]$rows.Add([pscustomobject][ordered]@{ App = $an; PID = [int]$w[1]; Type = $types[$w[2]] })
  }
}
if ($rows.Count -eq 0) { [pscustomobject][ordered]@{ App = 'Nothing is using this'; PID = ''; Type = '' } } else { $rows }

function Fmt([double]$b) {
  $c = [Globalization.CultureInfo]::InvariantCulture
  if ($b -lt 1024) { return ([int64]$b).ToString($c) + ' B' }
  if ($b -lt 1MB) { return [string]::Format($c, '{0:0.0} KB', $b / 1KB) }
  if ($b -lt 1GB) { return [string]::Format($c, '{0:0.0} MB', $b / 1MB) }
  return [string]::Format($c, '{0:0.0} GB', $b / 1GB)
}

function Get-Map([string]$base) {
  $m = @{}
  foreach ($f in (Get-ChildItem -LiteralPath $base -Recurse -File -ErrorAction SilentlyContinue)) { $m[$f.FullName.Substring($base.TrimEnd('\').Length + 1).ToLowerInvariant()] = $f }
  $m
}
function Hash-Of([string]$p) { [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([IO.File]::ReadAllBytes($p))) }
$paths = @({paths})
$a = $paths[0]; $b = $paths[1]
if ((Test-Path -LiteralPath $a -PathType Container) -and (Test-Path -LiteralPath $b -PathType Container)) {
  $ma = Get-Map $a; $mb = Get-Map $b
  $rows = New-Object System.Collections.ArrayList
  foreach ($k in ($ma.Keys + $mb.Keys | Sort-Object -Unique)) {
    $ia = $ma[$k]; $ib = $mb[$k]
    if ($ia -and -not $ib) { [void]$rows.Add([pscustomobject][ordered]@{ Result = 'Only in A'; File = $k; Detail = (Fmt $ia.Length) }) }
    elseif ($ib -and -not $ia) { [void]$rows.Add([pscustomobject][ordered]@{ Result = 'Only in B'; File = $k; Detail = (Fmt $ib.Length) }) }
    elseif ($ia.Length -ne $ib.Length -or (Hash-Of $ia.FullName) -ne (Hash-Of $ib.FullName)) { [void]$rows.Add([pscustomobject][ordered]@{ Result = 'Different'; File = $k; Detail = ((Fmt $ia.Length) + ' vs ' + (Fmt $ib.Length)) }) }
  }
  if ($rows.Count -eq 0) { [pscustomobject][ordered]@{ Result = 'Identical'; File = ''; Detail = 'Both folders have the same files with the same content' } } else { $rows }
} else {
  $ta = @(Get-Content -LiteralPath $a); $tb = @(Get-Content -LiteralPath $b)
  $diff = @(Compare-Object -ReferenceObject $ta -DifferenceObject $tb -CaseSensitive | Select-Object -First 500)
  if ($diff.Count -eq 0) { [pscustomobject][ordered]@{ Result = 'Identical'; File = ''; Detail = 'Both files have the same lines' } }
  else { foreach ($d in $diff) { [pscustomobject][ordered]@{ Result = $(if ($d.SideIndicator -eq '<=') { 'Only in A' } else { 'Only in B' }); File = ''; Detail = [string]$d.InputObject } } }
}

$paths = @({paths}) | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf }
$groups = @($paths | ForEach-Object { [pscustomobject]@{ Path = $_; Hash = [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([IO.File]::ReadAllBytes($_))) } } | Group-Object Hash)
if ($groups.Count -eq 1) { 'All {0} identical' -f $paths.Count } else { '{0} groups of identical files among {1}' -f $groups.Count, $paths.Count }

$root = {path}
$leaf = Split-Path -Leaf $root
$files = @(& git -C $root ls-files -co --exclude-standard 2>$null)
if ($LASTEXITCODE -ne 0 -or $files.Count -eq 0) { Write-Error 'This folder is not a git repository, or it has no files to zip.'; return }
$zipPath = Join-Path (Split-Path -Parent $root) ($leaf + '.zip')
if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [IO.Compression.ZipFile]::Open($zipPath, 'Create')
try { foreach ($f in $files) { $full = Join-Path $root ($f.Replace('/', '\')); if (Test-Path -LiteralPath $full -PathType Leaf) { [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $full, $f, 'Optimal') } } } finally { $zip.Dispose() }
'Created {0}.zip with {1} files' -f $leaf, $files.Count

$f = {path}
$dest = Join-Path (Split-Path -Parent $f) ([IO.Path]::GetFileNameWithoutExtension($f) -replace '\.tar$', '')
New-Item -ItemType Directory -Force -Path $dest | Out-Null
& tar.exe -xf $f -C $dest
if ($LASTEXITCODE -ne 0) { Write-Error 'tar could not read this archive.'; return }
'Extracted to ' + (Split-Path -Leaf $dest)

$f = {path}
$ext = [IO.Path]::GetExtension($f).ToLowerInvariant()
if ($ext -eq '.zip') {
  Add-Type -AssemblyName System.IO.Compression.FileSystem
  $z = [IO.Compression.ZipFile]::OpenRead($f)
  try { foreach ($e in $z.Entries) { if ($e.FullName.EndsWith('/')) { continue }; [pscustomobject][ordered]@{ Name = $e.FullName; Size = $e.Length; Packed = $e.CompressedLength } } } finally { $z.Dispose() }
} else {
  foreach ($l in (& tar.exe -tf $f)) { if ($l -and -not $l.EndsWith('/')) { [pscustomobject][ordered]@{ Name = $l; Size = ''; Packed = '' } } }
}

Add-Type -AssemblyName System.Drawing
$out = foreach ($p in @({paths})) { $i = [System.Drawing.Image]::FromFile($p); try { '{0}x{1}' -f $i.Width, $i.Height } finally { $i.Dispose() } }
@($out) -join "`n"

$p = {path}
$out = [IO.Path]::ChangeExtension($p, '.webp')
if (Get-Command magick -ErrorAction SilentlyContinue) { & magick $p $out } else { & ffmpeg -y -loglevel error -i $p $out }
if ($LASTEXITCODE -ne 0) { Write-Error 'The conversion failed.'; return }
'Created ' + (Split-Path -Leaf $out)

Set-Location -LiteralPath {dir}
$py = if (Get-Command python -ErrorAction SilentlyContinue) { 'python' } else { 'py' }
& $py -m venv .venv 2>&1
if ($LASTEXITCODE -ne 0) { return }
'Created .venv'
if (Test-Path -LiteralPath 'requirements.txt') { & .\.venv\Scripts\python.exe -m pip install -r requirements.txt 2>&1 }

$port = [int]{input:port}
$conns = @(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue)
if ($conns.Count -eq 0) { 'Nothing is listening on port ' + $port; return }
foreach ($c in $conns) {
  $proc = Get-Process -Id $c.OwningProcess -ErrorAction SilentlyContinue
  if ($proc) { 'Stopping {0} (PID {1}) on port {2}' -f $proc.ProcessName, $proc.Id, $port; Stop-Process -Id $proc.Id -Force }
}
